package com.mahesh.empleave.leave;import com.mahesh.empleave.user.*;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.*;import java.time.*;import java.util.*;public interface LeaveRepository extends JpaRepository<LeaveApplication,Long>{@Query("select l from LeaveApplication l where l.applicant=?1 and l.status in ('PENDING','APPROVED') and l.startDate <= ?3 and l.endDate >= ?2") List<LeaveApplication> overlaps(AppUser u,LocalDate from,LocalDate to);List<LeaveApplication> findByApplicantOrderByIdDesc(AppUser u);Page<LeaveApplication> findByApplicantOrderByIdDesc(AppUser u,Pageable p);Page<LeaveApplication> findByApplicantManagerOrderByIdDesc(AppUser manager,Pageable p);List<LeaveApplication> findByStatus(LeaveStatus s);}
